questionvariables.text:
scenario : rand(3);              /* 0: linear disguised, 1: quadratic disguised, 2: cubic disguised */
a : rand_with_prohib(1,4,[]);
b : rand_with_prohib(1,9,[]);
c : rand_with_prohib(1,9,[]);
rawexpr : if scenario=0 then (a*x+b)-(a*x-c)                     /* the x^1 terms cancel! looks linear, IS constant... use a safer disguised-linear */
          elseif scenario=1 then (x+a)*(x-a)+b*x
          else (x+a)*(x-a)*(x+b);
/* safer scenario 0: a genuine disguised linear (product of a linear and a constant factor) */
rawexpr : if scenario=0 then a*(x+b)-a*x+c*x
          elseif scenario=1 then (x+a)*(x-a)+b*x
          else (x+a)*(x-a)*(x+b);
degexpr : expand(rawexpr);
deg : hipow(degexpr,x);
ftype_opt : if deg=1 then "linear" elseif deg=2 then "quadratic" else "cubic";
opts : [["linear", deg=1, "Linear"],["quadratic", deg=2, "Quadratic"],["cubic", deg=3, "Cubic"]];
displayexpr : if scenario=0 then sconcat(a,"(x+",b,") - ",a,"x + ",c,"x")
              elseif scenario=1 then sconcat("(x+",a,")(x-",a,") + ",b,"x")
              else sconcat("(x+",a,")(x-",a,")(x+",b,")");
